use std::{collections::BTreeMap,time::{Instant,Duration}};
fn main(){
 let a:Vec<_>=std::env::args().collect();assert_eq!(a.len(),5);let m=mip_codex::mps::read(&a[1]).unwrap();let r:serde_json::Value=serde_json::from_slice(&std::fs::read(&a[2]).unwrap()).unwrap();let seed:Vec<f64>=m.variables.iter().map(|v|r["values"][&v.name].as_f64().unwrap()).collect();let repair=mip_codex::heuristic::Repair::new(&m);assert!(repair.candidate_check(&seed));let start=Instant::now();let duration: f64=a[3].parse().unwrap();let (x,stats)=repair.descend(&seed,start+Duration::from_secs_f64(duration)).unwrap();assert!(repair.candidate_check(&x));let sign=if m.maximize{-1.}else{1.};assert!(sign*m.objective(&x)<=sign*m.objective(&seed));let values:BTreeMap<_,_>=m.variables.iter().zip(&x).map(|(v,&x)|(v.name.clone(),x)).collect();let out=serde_json::json!({"status":"primal_candidate","objective":m.objective(&x),"dual_bound":null,"values":values,"component_seconds":start.elapsed().as_secs_f64(),"stats":stats,"purpose":"existing Rust generic objective descent on own feasible candidates; no global bound/optimality claim","source_fingerprint":mip_codex::BUILD_SOURCE_FINGERPRINT});std::fs::write(&a[4],serde_json::to_vec_pretty(&out).unwrap()).unwrap();println!("{}",serde_json::json!({"before":m.objective(&seed),"after":m.objective(&x),"seconds":out["component_seconds"]}));
}
